/**
 * A teaching simulation: a synthetic population with known truth is sampled repeatedly under several
 * designs, so that bias, standard errors, interval coverage and design effects can be seen rather than
 * asserted. The population is generated by the program and represents no real group of people.
 */
import { meanOf, randomNormal, seededRandom, sum, tCriticalAt, varianceOf } from './sampling-core.ts';
import { allocate } from './sampling.ts';
import { selectSrs, selectSystematic } from './sampling-selection.ts';

export type LabUnit = { stratum: number; cluster: number; x: number; y: number };
export type LabPopulation = { units: LabUnit[]; strata: { name: string; size: number; mean: number; sd: number }[]; clusterSize: number; clusters: number; Ybar: number; Xbar: number; rho: number; icc: number };
const STRATA = [{ name: '大一', size: 1800, mean: 1400 }, { name: '大二', size: 1650, mean: 1500 }, { name: '大三', size: 1500, mean: 1600 }, { name: '大四', size: 1050, mean: 1750 }];

/** 6 000 simulated students in 4 grades and 240 classes of 25: y is monthly spending, x is living allowance. */
export function makePopulation(seed = 'evix-lab'): LabPopulation {
  const rand = seededRandom(seed), units: LabUnit[] = [], clusterSize = 25;
  let cluster = 0;
  STRATA.forEach((s, h) => {
    for (let c = 0; c < s.size / clusterSize; c++, cluster++) {
      const classEffect = 120 * randomNormal(rand);
      for (let i = 0; i < clusterSize; i++) {
        const y = Math.max(300, s.mean + classEffect + 420 * randomNormal(rand));
        units.push({ stratum: h, cluster, y, x: Math.max(200, 200 + y + 300 * randomNormal(rand)) });
      }
    }
  });
  const ys = units.map(u => u.y), xs = units.map(u => u.x), Ybar = meanOf(ys), Xbar = meanOf(xs);
  const sxy = sum(units.map(u => (u.x - Xbar) * (u.y - Ybar))) / (units.length - 1), rho = sxy / Math.sqrt(varianceOf(xs) * varianceOf(ys));
  const classMeans = Array.from({ length: cluster }, (_, k) => meanOf(units.slice(k * clusterSize, (k + 1) * clusterSize).map(u => u.y)));
  const within = sum(Array.from({ length: cluster }, (_, k) => sum(units.slice(k * clusterSize, (k + 1) * clusterSize).map(u => (u.y - classMeans[k]) ** 2)))) / (units.length - cluster);
  const between = varianceOf(classMeans) - within / clusterSize;
  return { units, clusterSize, clusters: cluster, Ybar, Xbar, rho, icc: between / (between + within),
    strata: STRATA.map((s, h) => { const v = units.filter(u => u.stratum === h).map(u => u.y); return { name: s.name, size: s.size, mean: meanOf(v), sd: Math.sqrt(varianceOf(v)) }; }) };
}

export type LabDesign = 'srs' | 'proportional' | 'neyman' | 'cluster' | 'systematic' | 'ratio';
export const LAB_DESIGNS: Record<LabDesign, { label: string; detail: string }> = {
  srs: { label: '简单随机抽样', detail: '样本均值，方差按简单随机抽样公式' },
  proportional: { label: '分层·比例分配', detail: '按年级分层，各层样本与层规模成比例' },
  neyman: { label: '分层·Neyman 分配', detail: '按年级分层，标准差大的层多抽' },
  cluster: { label: '整群抽样', detail: '随机抽取班级，班内全部调查' },
  systematic: { label: '系统抽样', detail: '名单按生活费排序后等距抽取，方差用相邻差分近似' },
  ratio: { label: '比率估计', detail: '简单随机抽样 + 已知生活费总体均值' },
};
export type LabResult = { design: LabDesign; estimates: number[]; meanEstimate: number; bias: number; empiricalSe: number; meanSe: number; coverage: number; efficiency: number; sampleSize: number };

/** Draw `reps` samples of about n units under each design and summarise the sampling distribution. */
export function runLab(pop: LabPopulation, { n, reps, seed = 'lab', designs = Object.keys(LAB_DESIGNS) as LabDesign[] }: { n: number; reps: number; seed?: string; designs?: LabDesign[] }): LabResult[] {
  const N = pop.units.length, f = n / N, z = tCriticalAt(0.95, null);
  const strataUnits = pop.strata.map((_, h) => pop.units.filter(u => u.stratum === h));
  const prop = allocate(pop.strata.map((s, h) => ({ id: String(h), name: s.name, size: s.size, sd: s.sd })), n, 'proportional').rows.map(r => r.allocation);
  const ney = allocate(pop.strata.map((s, h) => ({ id: String(h), name: s.name, size: s.size, sd: s.sd })), n, 'neyman').rows.map(r => r.allocation);
  const sortedByX = [...pop.units].sort((a, b) => a.x - b.x), k = Math.max(2, Math.round(n / pop.clusterSize));
  const run = (design: LabDesign, r: number): { estimate: number; se: number; df: number | null; size: number } => {
    const tag = `${seed}/${design}/${r}`;
    if (design === 'srs' || design === 'ratio') {
      const sample = selectSrs(N, n, tag).map(i => pop.units[i - 1]), ys = sample.map(u => u.y);
      if (design === 'srs') return { estimate: meanOf(ys), se: Math.sqrt((1 - f) * varianceOf(ys) / n), df: n - 1, size: n };
      const xs = sample.map(u => u.x), R = meanOf(ys) / meanOf(xs), resid = sample.map(u => u.y - R * u.x);
      return { estimate: R * pop.Xbar, se: Math.sqrt((1 - f) / n * sum(resid.map(e => e * e)) / (n - 1)), df: n - 1, size: n };
    }
    if (design === 'proportional' || design === 'neyman') {
      const alloc = design === 'proportional' ? prop : ney;
      let est = 0, v = 0;
      strataUnits.forEach((units, h) => {
        const W = units.length / N, ys = selectSrs(units.length, alloc[h], `${tag}/${h}`).map(i => units[i - 1].y);
        est += W * meanOf(ys); v += W * W * (1 - alloc[h] / units.length) * varianceOf(ys) / alloc[h];
      });
      return { estimate: est, se: Math.sqrt(v), df: null, size: n };
    }
    if (design === 'cluster') {
      const picks = selectSrs(pop.clusters, k, tag), means = picks.map(c => meanOf(pop.units.slice((c - 1) * pop.clusterSize, c * pop.clusterSize).map(u => u.y)));
      return { estimate: meanOf(means), se: Math.sqrt((1 - k / pop.clusters) * varianceOf(means) / k), df: k - 1, size: k * pop.clusterSize };
    }
    const ys = selectSystematic(N, n, tag).positions.map(p => sortedByX[p - 1].y);
    let d = 0;
    for (let i = 1; i < ys.length; i++) d += (ys[i] - ys[i - 1]) ** 2;
    return { estimate: meanOf(ys), se: Math.sqrt((1 - f) / n * d / (2 * (n - 1))), df: n - 1, size: n };
  };
  const results = designs.map(design => {
    const runs = Array.from({ length: reps }, (_, r) => run(design, r)), estimates = runs.map(x => x.estimate);
    const covered = runs.filter(x => Math.abs(x.estimate - pop.Ybar) <= (x.df === null ? z : tCriticalAt(0.95, x.df)) * x.se).length;
    return { design, estimates, meanEstimate: meanOf(estimates), bias: meanOf(estimates) - pop.Ybar, empiricalSe: Math.sqrt(varianceOf(estimates)), meanSe: meanOf(runs.map(x => x.se)), coverage: covered / reps, efficiency: 1, sampleSize: runs[0].size };
  });
  // Efficiency against an SRS with the same number of interviews: (1 − m/N)S²/m ÷ empirical variance.
  const S2 = varianceOf(pop.units.map(u => u.y));
  for (const x of results) x.efficiency = (1 - x.sampleSize / N) * S2 / x.sampleSize / x.empiricalSe ** 2;
  return results;
}
